CREATE TABLE pest_disease_alerts(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`crop_id` bigint  NOT NULL,`farm_id` bigint  NOT NULL,`pest_disease_name` varchar(255)  NOT NULL COMMENT 'Name of pest or disease',`alert_type` varchar(50)  NOT NULL COMMENT 'pest or disease',`severity` varchar(50)  NOT NULL COMMENT 'low, medium, high',`description` text  NOT NULL,`crop_stage` varchar(100)  NOT NULL COMMENT 'Growth stage when detected',`weather_conditions` text  NULL COMMENT 'JSON of weather conditions at detection',`organic_recommendations` text  NULL COMMENT 'JSON array of organic treatment options',`chemical_recommendations` text  NULL COMMENT 'JSON array of chemical treatment options',`prevention_measures` text  NULL COMMENT 'JSON array of prevention measures',`timing_instructions` text  NULL COMMENT 'Application timing guidance',`notification_sent` TINYINT(1)  DEFAULT 0,`notification_sent_at` timestamp  NULL,`is_resolved` TINYINT(1)  DEFAULT 0,`resolved_at` timestamp  NULL)ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;